using System;using System.Data;using System.Text;public partial class Games:System.Web.UI.Page{public string gamesHtml="",SearchText="",AllChecked="checked='checked'",EnglandChecked="",SpainChecked="";protected void Page_Load(object sender,EventArgs e){string league="All";if(Page.IsPostBack){league=Request.Form["league"]??"All";SearchText=MyAdoHelper.FixText(Request.Form["searchText"]);}if(league=="England"){AllChecked="";EnglandChecked="checked='checked'";}if(league=="Spain"){AllChecked="";SpainChecked="checked='checked'";}string where=" WHERE 1=1 ";if(league!="All")where+=" AND Games.League=N'"+league+"'";if(SearchText!="")where+=" AND (A.ClubName LIKE N'%"+SearchText+"%' OR B.ClubName LIKE N'%"+SearchText+"%')";string sql="SELECT Games.GameId,Games.GameDate,Games.League,Games.GameResult,Games.ClubAId,Games.ClubBId,A.ClubName ClubA,B.ClubName ClubB,(SELECT COUNT(DISTINCT UserId) FROM Bets WHERE Bets.GameId=Games.GameId) Bettors FROM Games INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId"+where+" ORDER BY Games.GameDate";DataTable dt=MyAdoHelper.ExecuteDataTable(sql);StringBuilder s=new StringBuilder();for(int i=0;i<dt.Rows.Count;i++){string r=dt.Rows[i]["GameResult"].ToString();if(r=="-1")r="טרם התקיים";string a=dt.Rows[i]["ClubA"].ToString(),b=dt.Rows[i]["ClubB"].ToString();s.Append("<div class='card'><div class='teamRow'><div class='teamBox'><img class='teamIcon' src='Images/Clubs/"+Icon(a)+"'/><br/>"+a+"</div><b>נגד</b><div class='teamBox'><img class='teamIcon' src='Images/Clubs/"+Icon(b)+"'/><br/>"+b+"</div></div><p>ליגה: "+dt.Rows[i]["League"]+"</p><p>תאריך: "+Convert.ToDateTime(dt.Rows[i]["GameDate"]).ToString("dd/MM/yyyy HH:mm")+"</p><p class='result'>תוצאה: "+r+"</p><p>מספר מהמרים: "+dt.Rows[i]["Bettors"]+"</p></div>");}gamesHtml=s.ToString();}private string Icon(string n){return n.Replace(" ","").ToLower()+".svg";}}